# Module: services/api-gateway/src/api_gateway/repository.py — Release Notes Catalog Reader
# Invariants: Reads signed releases/notes/*.json generated by ./signal.sh release (20-*).
# Spec: architecture/20-versioning-release-monorepo-build-and-k8s-topology.md
from __future__ import annotations

import json
from pathlib import Path

from api_gateway.schemas import PlatformReleaseDto

REPO_ROOT = Path(__file__).resolve().parents[4]


async def load_platform_releases() -> list[PlatformReleaseDto]:
    notes_dir = REPO_ROOT / "releases" / "notes"
    items: list[PlatformReleaseDto] = []
    for path in sorted(notes_dir.glob("v*.json"), reverse=True):
        raw = json.loads(path.read_text(encoding="utf-8"))
        items.append(PlatformReleaseDto.model_validate(raw))
    return items
